import { Client } from '/harness-state/.bun/install/global/node_modules/@modelcontextprotocol/sdk/dist/esm/client/index.js';
import { StdioClientTransport } from '/harness-state/.bun/install/global/node_modules/@modelcontextprotocol/sdk/dist/esm/client/stdio.js';
import { randomUUID } from 'node:crypto';
import { writeFileSync } from 'node:fs';
const marker='install-mcp-'+randomUUID();
const entity='concepts/gbrain-mcp-verification';
let client;
async function connect(){const c=new Client({name:'gbrain-install-check',version:'1.0.0'});await c.connect(new StdioClientTransport({command:'/workspace/bin/gbrain-run',args:['serve','--surface','starter','--advertise','verbs'],stderr:'inherit',cwd:'/harness-state/.gbrain'}));return c;}
async function call(name,args){const r=await client.callTool({name,arguments:args});console.log(JSON.stringify({tool:name,response:r}));if(r.isError)throw Error('MCP '+name+' failed');return JSON.parse(r.content[0].text);}
let id;const proof={transport:'stdio',native_openclaw_discovery:'unverified',marker};
try{
 client=await connect();
 const saved=await call('remember',{fact:'Synthetic GBrain MCP verification marker: '+marker,entity,provenance:'install-check',request_id:randomUUID()});
 id=String(saved.id??saved.outcome?.id);if(!id||id==='undefined')throw Error('Missing fact id');proof.fact_id=id;
 let recalled=await call('recall',{entity});if(!JSON.stringify(recalled).includes(marker))throw Error('Recall did not return marker');proof.same_session_recall=true;
 await client.close();client=await connect();
 recalled=await call('recall',{entity});if(!JSON.stringify(recalled).includes(marker))throw Error('Reopened MCP did not return marker');proof.reopened_server_recall=true;
 await call('forget',{id,reason:'install-check cleanup',request_id:randomUUID()});
 const clean=await call('recall',{entity});if(JSON.stringify(clean).includes(marker))throw Error('Marker still active');proof.cleanup_verified=true;
 writeFileSync('/tmp/gbrain-native-setup/mcp-proof.json',JSON.stringify(proof,null,2)+'\n');
 console.log(JSON.stringify({verified:proof}));
}finally{if(client)await client.close();}

